package com.stayhaven.web;

import com.stayhaven.domain.*;
import com.stayhaven.repo.*;
import com.stayhaven.service.BookingService;
import com.stayhaven.web.Forms.*;
import jakarta.validation.Valid;
import org.springframework.data.domain.Sort;
import org.springframework.security.core.Authentication;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.*;

@Controller public class WebController {
 private record RecentGuestView(Long accountId,String guestName,long stays,double spend,LocalDate lastStay,boolean returning){}
 private final AccountRepository accounts; private final HotelRepository hotels; private final RoomRepository rooms; private final BookingRepository bookings; private final BookingService bookingService; private final PasswordEncoder encoder; private final com.stayhaven.repo.RoomUnitRepository units; private final com.stayhaven.repo.RoomStatusHistoryRepository roomHistory; private final com.stayhaven.repo.ReviewRepository reviews; private final com.stayhaven.repo.PaymentRepository payments; private final com.stayhaven.repo.RoomServiceOrderRepository serviceOrders; private final com.stayhaven.repo.OfferRepository offers; private final com.stayhaven.repo.LoyaltyTransactionRepository loyalty; private final com.stayhaven.service.PaymentProcessor paymentProcessor;
 public WebController(AccountRepository a,HotelRepository h,RoomRepository r,BookingRepository b,BookingService s,PasswordEncoder e,com.stayhaven.repo.RoomUnitRepository u,com.stayhaven.repo.RoomStatusHistoryRepository rh,com.stayhaven.repo.ReviewRepository rv,com.stayhaven.repo.PaymentRepository p,com.stayhaven.repo.RoomServiceOrderRepository so,com.stayhaven.repo.OfferRepository o,com.stayhaven.repo.LoyaltyTransactionRepository l,com.stayhaven.service.PaymentProcessor pp){accounts=a;hotels=h;rooms=r;bookings=b;bookingService=s;encoder=e;units=u;roomHistory=rh;reviews=rv;payments=p;serviceOrders=so;offers=o;loyalty=l;paymentProcessor=pp;}
 private Account current(Authentication auth){return accounts.findByEmail(auth.getName()).orElseThrow();}
 @GetMapping("/") public String home(@RequestParam(required=false)String location,@RequestParam(required=false)String checkIn,@RequestParam(required=false)String checkOut,@RequestParam(required=false)Integer guests,Model m){m.addAttribute("hotels",location==null||location.isBlank()?hotels.findAll():hotels.findByLocationContainingIgnoreCase(location));m.addAttribute("location",location);m.addAttribute("checkIn",checkIn);m.addAttribute("checkOut",checkOut);m.addAttribute("guests",guests);return "home";}
 @GetMapping("/login") public String login(Model m){m.addAttribute("adminLogin",false);return "login";}
 @GetMapping("/admin/login") public String adminLogin(Model m){m.addAttribute("adminLogin",true);return "login";}
 @GetMapping("/register") public String register(Model m){m.addAttribute("form",new Registration());return "register";}
 @PostMapping("/register") public String registerPost(@Valid @ModelAttribute("form")Registration form,BindingResult result,Model m,RedirectAttributes flash){
  if(accounts.findByEmail(form.getEmail()).isPresent())result.rejectValue("email","duplicate","An account with this email already exists.");
  if(result.hasErrors())return "register";Account a=new Account();a.setName(form.getName());a.setEmail(form.getEmail());a.setPhone(form.getPhone());a.setAddress(form.getAddress());a.setPassword(encoder.encode(form.getPassword()));accounts.save(a);flash.addFlashAttribute("success","Account created. Please sign in.");return "redirect:/login";}
 @GetMapping("/hotels/{id}") public String hotel(@PathVariable Long id,@RequestParam(required=false)String checkIn,@RequestParam(required=false)String checkOut,@RequestParam(required=false)Integer guests,Authentication auth,Model m){Hotel h=hotels.findById(id).orElseThrow();var roomList=rooms.findByHotelId(id);m.addAttribute("hotel",h);m.addAttribute("rooms",roomList);m.addAttribute("hotelReviews",reviews.findByBookingRoomHotelIdOrderByCreatedAtDesc(id));m.addAttribute("checkIn",checkIn);m.addAttribute("checkOut",checkOut);m.addAttribute("guests",guests==null?1:guests);m.addAttribute("bookingForm",new BookingForm());boolean signedIn=auth!=null&&auth.isAuthenticated()&&accounts.findByEmail(auth.getName()).isPresent();m.addAttribute("loyaltyBalance",signedIn?loyalty.balance(current(auth).getId()):0);if(checkIn!=null&&!checkIn.isBlank()&&checkOut!=null&&!checkOut.isBlank()){try{LocalDate in=LocalDate.parse(checkIn),out=LocalDate.parse(checkOut);if(!in.isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata")))||!out.isAfter(in))m.addAttribute("availabilityError","Select future dates with check-out after check-in.");else{java.util.Map<Long,Long> available=new java.util.HashMap<>();for(Room room:roomList)available.put(room.getId(),units.findByRoomId(room.getId()).stream().filter(u->!Set.of("MAINTENANCE","CLEANING").contains(u.getStatus())&&bookings.countOverlappingUnit(u.getId(),in,out)==0).count());m.addAttribute("availability",available);}}catch(java.time.format.DateTimeParseException ex){m.addAttribute("availabilityError","Enter valid check-in and check-out dates.");}}return "hotel";}
 @PostMapping("/bookings/new") public String book(@Valid @ModelAttribute("bookingForm")BookingForm f,BindingResult result,Authentication auth,Model m,RedirectAttributes flash){if(result.hasErrors()){flash.addFlashAttribute("error","Check your guest details and travel dates.");return "redirect:/hotels/"+f.getHotelId();}try{Booking b=bookingService.create(current(auth),f.getRoomId(),f.getCheckIn(),f.getCheckOut(),f.getGuests(),f.getGuestName(),f.getGuestEmail(),f.getOfferCode(),f.getLoyaltyPoints());return "redirect:/bookings/confirmation/"+b.getId();}catch(IllegalArgumentException ex){flash.addFlashAttribute("error",ex.getMessage());return "redirect:/hotels/"+f.getHotelId();}}
 @GetMapping("/dashboard") public String dashboard(Authentication auth,Model m){Account a=current(auth);m.addAttribute("account",a);m.addAttribute("bookings",bookings.findByAccountIdOrderByCheckInDesc(a.getId()));return "dashboard";}
 @GetMapping("/bookings/confirmation/{id}") public String confirmation(@PathVariable Long id,Authentication auth,Model m){Booking b=bookings.findById(id).orElseThrow();if(!b.getAccount().getId().equals(current(auth).getId()))return "error/403";m.addAttribute("booking",b);return "confirmation";}
 @PostMapping("/bookings/{id}/cancel") public String cancel(@PathVariable Long id,Authentication auth,RedirectAttributes f){Booking b=bookings.findById(id).orElseThrow();if(!b.getAccount().getId().equals(current(auth).getId()))return "error/403";if(b.getStatus().equals("CONFIRMED")&&b.getCheckIn().isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata")))){bookingService.updateStatus(id,"CANCELLED");f.addFlashAttribute("success","Booking cancelled. Any demo payment is marked for test refund review; no real refund is processed.");}else f.addFlashAttribute("error","This booking cannot be cancelled.");return "redirect:/dashboard";}
 @GetMapping("/profile") public String profile(Authentication auth,Model m){m.addAttribute("account",current(auth));return "profile";}
 @PostMapping("/profile") public String updateProfile(@RequestParam String name,@RequestParam String phone,@RequestParam(required=false)String address,Authentication auth,RedirectAttributes f){Account a=current(auth);if(name.isBlank()||phone.isBlank()){f.addFlashAttribute("error","Name and phone are required.");return "redirect:/profile";}a.setName(name.trim());a.setPhone(phone.trim());a.setAddress(address==null?null:address.trim());accounts.save(a);f.addFlashAttribute("success","Profile updated.");return "redirect:/profile";}
 @GetMapping("/admin") public String admin(Model m){LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));var all=bookings.findAll(Sort.by(Sort.Direction.DESC,"id"));var upcoming=all.stream().filter(b->b.getCheckIn()!=null&&!b.getCheckIn().isBefore(today)&&Set.of("CONFIRMED","PENDING").contains(b.getStatus())).sorted(Comparator.comparing(Booking::getCheckIn)).limit(8).toList();var completed=all.stream().filter(b->"CHECKED OUT".equals(b.getStatus())).sorted(Comparator.comparing(Booking::getCheckOut).reversed()).toList();var paymentRows=payments.findAllByOrderByCreatedAtDesc();Map<Long,Long> stayCounts=new HashMap<>();Map<Long,Double> paidByGuest=new HashMap<>();Map<Long,LocalDate> lastStayByGuest=new HashMap<>();for(Booking b:completed){stayCounts.merge(b.getAccount().getId(),1L,Long::sum);lastStayByGuest.putIfAbsent(b.getAccount().getId(),b.getCheckOut());}for(Payment p:paymentRows)paidByGuest.merge(p.getBooking().getAccount().getId(),p.getAmount(),Double::sum);List<RecentGuestView> recent=new ArrayList<>();Set<Long> recentIds=new HashSet<>();for(Booking b:completed)if(recentIds.add(b.getAccount().getId())&&recent.size()<8){long stays=stayCounts.getOrDefault(b.getAccount().getId(),0L);recent.add(new RecentGuestView(b.getAccount().getId(),b.getGuestName(),stays,paidByGuest.getOrDefault(b.getAccount().getId(),0d),lastStayByGuest.get(b.getAccount().getId()),stays>1));}m.addAttribute("hotelCount",hotels.count());m.addAttribute("totalRooms",units.count());m.addAttribute("availableRooms",units.countByStatus("AVAILABLE"));m.addAttribute("occupiedRooms",units.countByStatus("OCCUPIED"));m.addAttribute("cleaningRooms",units.countByStatus("CLEANING"));m.addAttribute("maintenanceRooms",units.countByStatus("MAINTENANCE"));long reserved=upcoming.stream().map(Booking::getRoomUnit).filter(Objects::nonNull).map(RoomUnit::getId).distinct().count();m.addAttribute("reservedRooms",reserved);m.addAttribute("availableRooms",Math.max(0,units.countByStatus("AVAILABLE")-reserved));m.addAttribute("users",accounts.countByRole("USER"));m.addAttribute("activeBookings",all.stream().filter(b->Set.of("PENDING","CONFIRMED","CHECKED IN").contains(b.getStatus())).count());m.addAttribute("todayCheckIns",bookings.countStatusArrivals("CONFIRMED",today));m.addAttribute("todayCheckOuts",bookings.countStatusDepartures("CHECKED IN",today));m.addAttribute("checkedInGuests",all.stream().filter(b->"CHECKED IN".equals(b.getStatus())).mapToLong(Booking::getGuests).sum());m.addAttribute("revenue",paymentRows.stream().mapToDouble(Payment::getAmount).sum());m.addAttribute("averageRating",reviews.averageRating());m.addAttribute("allBookings",all);m.addAttribute("upcomingBookings",upcoming);m.addAttribute("recentGuests",recent);return "admin/dashboard";}
 @GetMapping("/admin/rooms") public String adminRooms(@RequestParam(required=false)String q,Model m){var list=units.findAllByOrderByRoomNumberAsc();if(q!=null&&!q.isBlank())list=list.stream().filter(u->u.getRoomNumber().contains(q)||u.getRoom().getType().toLowerCase().contains(q.toLowerCase())||u.getRoom().getHotel().getName().toLowerCase().contains(q.toLowerCase())).toList();var all=bookings.findAll();Map<Long,Booking> current=new HashMap<>();for(Booking b:all)if(b.getRoomUnit()!=null&&Set.of("PENDING","CONFIRMED","CHECKED IN").contains(b.getStatus())){Booking prev=current.get(b.getRoomUnit().getId());if(prev==null||b.getCheckIn().isBefore(prev.getCheckIn()))current.put(b.getRoomUnit().getId(),b);}Map<Long,String> displayStatus=new HashMap<>();for(var u:list){Booking b=current.get(u.getId());displayStatus.put(u.getId(),b!=null&&"CONFIRMED".equals(b.getStatus())&&"AVAILABLE".equals(u.getStatus())?"RESERVED":u.getStatus());}m.addAttribute("units",list);m.addAttribute("current",current);m.addAttribute("displayStatus",displayStatus);m.addAttribute("q",q);return "admin/rooms";}
 @GetMapping("/admin/rooms/{id}") public String adminRoomDetail(@PathVariable Long id,Model m){var u=units.findWithRoomById(id).orElseThrow();var history=bookings.findAll().stream().filter(b->b.getRoomUnit()!=null&&b.getRoomUnit().getId().equals(id)).sorted(Comparator.comparing(Booking::getCheckIn).reversed()).toList();m.addAttribute("unit",u);m.addAttribute("history",history);m.addAttribute("statusHistory",roomHistory.findByRoomUnitIdOrderByChangedAtDesc(id));return "admin/room-detail";}
 @PostMapping("/admin/rooms/{id}/status") public String roomStatus(@PathVariable Long id,@RequestParam String status,Authentication auth,RedirectAttributes f){try{bookingService.updateRoomStatus(id,status,current(auth));f.addFlashAttribute("success","Room status updated.");}catch(IllegalArgumentException ex){f.addFlashAttribute("error",ex.getMessage());}return "redirect:/admin/rooms";}
 @GetMapping("/admin/check-ins") public String checkIns(@RequestParam(required=false) LocalDate date,Model m){LocalDate selected=date==null?LocalDate.now(java.time.ZoneId.of("Asia/Kolkata")):date;var eligible=bookings.findArrivalsOn(selected).stream().filter(b->"CONFIRMED".equals(b.getStatus())&&b.getRoomUnit()!=null&&"AVAILABLE".equals(b.getRoomUnit().getStatus())).toList();m.addAttribute("bookings",eligible);m.addAttribute("today",selected);m.addAttribute("selectedDate",selected);m.addAttribute("isToday",selected.equals(LocalDate.now(java.time.ZoneId.of("Asia/Kolkata"))));return "admin/check-ins";}
 @GetMapping("/admin/check-outs") public String checkOuts(Model m){var list=new ArrayList<>(bookings.findByCheckOut(LocalDate.now(ZoneId.of("Asia/Kolkata"))).stream().filter(b->"CHECKED IN".equals(b.getStatus())).toList());list.addAll(bookings.findByStatus("CHECKED IN").stream().filter(b->!b.getCheckOut().equals(LocalDate.now(ZoneId.of("Asia/Kolkata")))).toList());m.addAttribute("bookings",list);return "admin/check-outs";}
 @PostMapping("/admin/bookings/{id}/check-in") public String doCheckIn(@PathVariable Long id,Authentication auth,RedirectAttributes f){try{bookingService.checkIn(id,current(auth));f.addFlashAttribute("success","Guest checked in.");}catch(IllegalArgumentException e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/check-ins";}
 @PostMapping("/admin/bookings/{id}/check-out") public String doCheckOut(@PathVariable Long id,Authentication auth,RedirectAttributes f){try{bookingService.checkOut(id,current(auth));f.addFlashAttribute("success","Guest checked out. Room moved to cleaning.");}catch(IllegalArgumentException e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/check-outs";}
 @GetMapping("/admin/guests") public String guests(@RequestParam(required=false)String q,Model m){var list=accounts.findAll(Sort.by("name")).stream().filter(a->"USER".equals(a.getRole())).filter(a->q==null||q.isBlank()||a.getName().toLowerCase().contains(q.toLowerCase())||a.getEmail().toLowerCase().contains(q.toLowerCase())).toList();m.addAttribute("guests",list);m.addAttribute("q",q);return "admin/guests";}
 @GetMapping("/admin/guests/{id}") public String guestDetail(@PathVariable Long id,@RequestParam(required=false)String status,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,Model m){Account a=accounts.findById(id).orElseThrow();if(!"USER".equals(a.getRole()))throw new IllegalArgumentException("Guest not found");var all=bookings.findByAccountIdOrderByCheckInDesc(id);var history=all.stream().filter(b->status==null||status.isBlank()||b.getStatus().equals(status)).filter(b->from==null||!b.getCheckIn().isBefore(from)).filter(b->to==null||!b.getCheckIn().isAfter(to)).toList();m.addAttribute("guest",a);m.addAttribute("bookings",history);m.addAttribute("stays",all.stream().filter(b->"CHECKED OUT".equals(b.getStatus())).count());m.addAttribute("spent",payments.findAllByOrderByCreatedAtDesc().stream().filter(p->p.getBooking().getAccount().getId().equals(id)).mapToDouble(Payment::getAmount).sum());m.addAttribute("statusFilter",status);m.addAttribute("from",from);m.addAttribute("to",to);m.addAttribute("guestReviews",reviews.findByGuestIdOrderByCreatedAtDesc(id));return "admin/guest-detail";}
 @GetMapping("/admin/guest-history") public String guestHistory(@RequestParam(required=false)String q,Model m){m.addAttribute("guests",accounts.findAll(Sort.by("name")).stream().filter(a->"USER".equals(a.getRole())).filter(a->q==null||q.isBlank()||a.getName().toLowerCase().contains(q.toLowerCase())||a.getEmail().toLowerCase().contains(q.toLowerCase())).toList());m.addAttribute("q",q);return "admin/guests";}
 @GetMapping("/admin/reviews") public String adminReviews(Model m){m.addAttribute("reviews",reviews.findAllByOrderByCreatedAtDesc());m.addAttribute("averageRating",reviews.averageRating());return "admin/reviews";}
 @PostMapping("/bookings/{id}/review") public String review(@PathVariable Long id,@RequestParam int rating,@RequestParam(required=false)String comment,Authentication auth,RedirectAttributes f){Booking b=bookings.findById(id).orElseThrow();Account a=current(auth);if(!b.getAccount().getId().equals(a.getId())||!"CHECKED OUT".equals(b.getStatus())||rating<1||rating>5||reviews.existsByBookingId(id)){f.addFlashAttribute("error","A review is only available once after your completed stay.");return "redirect:/dashboard";}com.stayhaven.domain.Review rv=new com.stayhaven.domain.Review();rv.setBooking(b);rv.setGuest(a);rv.setRating(rating);rv.setComment(comment==null?"":comment.trim());reviews.save(rv);f.addFlashAttribute("success","Thank you for your review.");return "redirect:/dashboard";}
 @PostMapping("/bookings/{id}/demo-payment") public String demoPayment(@PathVariable Long id,Authentication auth,RedirectAttributes f){Booking b=bookings.findById(id).orElseThrow();Account a=current(auth);if(!b.getAccount().getId().equals(a.getId())||!"CONFIRMED".equals(b.getStatus())||payments.existsByBookingId(id)){f.addFlashAttribute("error","This booking is not eligible for a demo payment.");return "redirect:/dashboard";}var attempt=paymentProcessor.process(b);com.stayhaven.domain.Payment p=new com.stayhaven.domain.Payment();p.setBooking(b);p.setAmount(attempt.amount());p.setProvider(attempt.provider());p.setStatus(attempt.status());p.setTransactionReference(attempt.reference());payments.save(p);b.setPaymentStatus("DEMO PAID");bookings.save(b);f.addFlashAttribute("success","Demo payment recorded for testing. No real payment was processed.");return "redirect:/bookings/confirmation/"+id;}
 @GetMapping("/admin/payments") public String adminPayments(Model m){m.addAttribute("payments",payments.findAllByOrderByCreatedAtDesc());m.addAttribute("bookings",bookings.findAll(Sort.by(Sort.Direction.DESC,"id")));return "admin/payments";}
 @GetMapping("/admin/reports") public String reports(Model m){admin(m);return "admin/reports";}
 @GetMapping("/admin/settings") public String settings(Model m){m.addAttribute("adminEmail",System.getenv().getOrDefault("STAYHAVEN_ADMIN_EMAIL","admin@stayhaven.local"));m.addAttribute("emailMode","Development mode; confirmation page is available, email is not sent");m.addAttribute("databaseMode",System.getenv().getOrDefault("DB_URL","H2 local file"));return "admin/settings";}
 @GetMapping("/admin/room-service") public String roomService(Model m){m.addAttribute("orders",serviceOrders.findAllByOrderByCreatedAtDesc());m.addAttribute("bookings",bookings.findByStatus("CHECKED IN").stream().filter(b->b.getRoomUnit()!=null&&"OCCUPIED".equals(b.getRoomUnit().getStatus())).toList());return "admin/room-service";}
 @PostMapping("/admin/room-service") public String createServiceOrder(@RequestParam Long bookingId,@RequestParam String item,@RequestParam int quantity,RedirectAttributes f){Booking b=bookings.findById(bookingId).orElseThrow();Map<String,Double> menu=Map.of("Breakfast",450.0,"Lunch tray",650.0,"Dinner tray",750.0,"Laundry bag",300.0,"Extra towels",0.0);Double price=menu.get(item);if(!"CHECKED IN".equals(b.getStatus())||price==null||quantity<1||quantity>20){f.addFlashAttribute("error","Choose an in-house booking, valid menu item and quantity (1–20).");return "redirect:/admin/room-service";}RoomServiceOrder o=new RoomServiceOrder();o.setBooking(b);o.setRoomUnit(b.getRoomUnit());o.setOrderedBy(b.getAccount());o.setItemName(item);o.setQuantity(quantity);o.setUnitPrice(price);serviceOrders.save(o);f.addFlashAttribute("success","Room-service order created.");return "redirect:/admin/room-service";}
 @PostMapping("/admin/room-service/{id}/status") public String roomServiceStatus(@PathVariable Long id,@RequestParam String status,RedirectAttributes f){if(!Set.of("PREPARING","DELIVERED","CANCELLED").contains(status)){f.addFlashAttribute("error","Invalid order status.");}else{RoomServiceOrder o=serviceOrders.findById(id).orElseThrow();if("CANCELLED".equals(o.getStatus())||"DELIVERED".equals(o.getStatus()))f.addFlashAttribute("error","This order is already closed.");else{o.setStatus(status);serviceOrders.save(o);}}return "redirect:/admin/room-service";}
 @GetMapping("/admin/offers") public String offers(Model m){m.addAttribute("offers",offers.findAllByOrderByStartsOnDesc());m.addAttribute("roomTypes",rooms.findAll());return "admin/offers";}
 @PostMapping("/admin/offers") public String addOffer(@RequestParam String name,@RequestParam String code,@RequestParam String discountType,@RequestParam double discountValue,@RequestParam LocalDate startsOn,@RequestParam LocalDate endsOn,@RequestParam(required=false)String applicableRoomType,RedirectAttributes f){if(name.isBlank()||code.isBlank()||!Set.of("PERCENT","FIXED").contains(discountType)||discountValue<=0||("PERCENT".equals(discountType)&&discountValue>100)||startsOn.isBefore(LocalDate.now(ZoneId.of("Asia/Kolkata")))||endsOn.isBefore(startsOn)||offers.findByCodeIgnoreCase(code).isPresent()){f.addFlashAttribute("error","Check offer fields, dates and uniqueness. Percent discounts must be at most 100%.");return "redirect:/admin/offers";}Offer o=new Offer();o.setName(name.trim());o.setCode(code.trim().toUpperCase(Locale.ROOT));o.setDiscountType(discountType);o.setDiscountValue(discountValue);o.setStartsOn(startsOn);o.setEndsOn(endsOn);o.setApplicableRoomType(applicableRoomType);offers.save(o);f.addFlashAttribute("success","Offer created and activated.");return "redirect:/admin/offers";}
 @PostMapping("/admin/offers/{id}/edit") public String editOffer(@PathVariable Long id,@RequestParam String name,@RequestParam double discountValue,@RequestParam LocalDate startsOn,@RequestParam LocalDate endsOn,@RequestParam(required=false)String applicableRoomType,RedirectAttributes f){Offer o=offers.findById(id).orElseThrow();if(name.isBlank()||discountValue<=0||("PERCENT".equals(o.getDiscountType())&&discountValue>100)||endsOn.isBefore(startsOn)){f.addFlashAttribute("error","Offer values or dates are invalid.");}else{o.setName(name.trim());o.setDiscountValue(discountValue);o.setStartsOn(startsOn);o.setEndsOn(endsOn);o.setApplicableRoomType(applicableRoomType);offers.save(o);f.addFlashAttribute("success","Offer updated.");}return "redirect:/admin/offers";}
 @PostMapping("/admin/offers/{id}/toggle") public String toggleOffer(@PathVariable Long id){Offer o=offers.findById(id).orElseThrow();o.setActive(!o.isActive());offers.save(o);return "redirect:/admin/offers";}
 @GetMapping("/admin/loyalty") public String loyaltyPage(Model m){m.addAttribute("transactions",loyalty.findAllByOrderByCreatedAtDesc());m.addAttribute("rule","Earn 1 point per ₹100 of completed stay value. Redeem in multiples of 100 points at ₹1 per point on future bookings.");return "admin/loyalty";}
 @GetMapping("/api/loyalty/balance") @ResponseBody public Map<String,Object> loyaltyBalance(Authentication auth){Account a=current(auth);return Map.of("points",loyalty.balance(a.getId()),"rule","Earn 1 point per ₹100 completed stay; redeem 100 points for ₹100 off.");}
 @GetMapping("/admin/hotels") public String adminHotels(@RequestParam(required=false)String q,Model m){var list=hotels.findAllWithRooms();if(q!=null&&!q.isBlank()){String term=q.trim().toLowerCase(Locale.ROOT);list=list.stream().filter(h->h.getName().toLowerCase(Locale.ROOT).contains(term)||h.getLocation().toLowerCase(Locale.ROOT).contains(term)||(h.getAddress()!=null&&h.getAddress().toLowerCase(Locale.ROOT).contains(term))).toList();}m.addAttribute("hotels",list);m.addAttribute("q",q);m.addAttribute("hotel",new Hotel());return "admin/hotels";}
 @PostMapping("/admin/hotels") public String addHotel(@Valid @ModelAttribute("hotelForm") HotelForm form,BindingResult result,RedirectAttributes f){if(result.hasErrors()){f.addFlashAttribute("error","Enter a name, location, description, and a rating from 0 to 5.");return "redirect:/admin/hotels";}Hotel hotel=new Hotel();hotel.setName(form.getName().trim());hotel.setLocation(form.getLocation().trim());hotel.setAddress(form.getAddress());hotel.setDescription(form.getDescription().trim());hotel.setRating(form.getRating());if(form.getImageUrl()!=null&&!form.getImageUrl().isBlank())hotel.setImageUrl(form.getImageUrl().trim());hotels.save(hotel);f.addFlashAttribute("success","Hotel added. Add room types below.");return "redirect:/admin/hotels";}
 @PostMapping("/admin/hotels/{id}/edit") public String editHotel(@PathVariable Long id,@RequestParam String name,@RequestParam String location,@RequestParam String description,@RequestParam(defaultValue="4.5") double rating,@RequestParam(required=false) String imageUrl,@RequestParam(required=false) String address,RedirectAttributes f){Hotel h=hotels.findById(id).orElseThrow();if(name.isBlank()||location.isBlank()||description.isBlank()||rating<0||rating>5){f.addFlashAttribute("error","Enter valid hotel details and a rating from 0 to 5.");return "redirect:/admin/hotels";}h.setName(name.trim());h.setLocation(location.trim());h.setAddress(address==null||address.isBlank()?null:address.trim());h.setDescription(description.trim());h.setRating(rating);h.setImageUrl(imageUrl);hotels.save(h);f.addFlashAttribute("success","Hotel details saved.");return "redirect:/admin/hotels";}
 @PostMapping("/admin/hotels/{id}/delete") public String deleteHotel(@PathVariable Long id,RedirectAttributes f){if(bookings.findAll().stream().anyMatch(b->b.getRoom().getHotel().getId().equals(id))){f.addFlashAttribute("error","Hotel has booking history and cannot be deleted.");}else{var hotel=hotels.findById(id).orElseThrow();for(Room room:rooms.findByHotelId(id))units.deleteAll(units.findByRoomId(room.getId()));hotels.deleteById(id);f.addFlashAttribute("success","Hotel removed.");}return "redirect:/admin/hotels";}
 @PostMapping("/admin/hotels/{id}/rooms") public String addRoom(@PathVariable Long id,@Valid @ModelAttribute("roomForm") RoomForm form,BindingResult result,RedirectAttributes f){if(result.hasErrors()){f.addFlashAttribute("error","Enter a room name, description, price, capacity and quantity.");return "redirect:/admin/hotels";}Room room=new Room();room.setHotel(hotels.findById(id).orElseThrow());room.setType(form.getType().trim());room.setDescription(form.getDescription().trim());room.setPricePerNight(form.getPricePerNight());room.setCapacity(form.getCapacity());room.setQuantity(form.getQuantity());room=rooms.save(room);for(int i=1;i<=room.getQuantity();i++){RoomUnit unit=new RoomUnit();unit.setRoom(room);unit.setRoomNumber(String.valueOf((room.getId()%9+1)*100+i));unit.setFloor((i-1)/10+1);unit.setBedType(room.getType().toLowerCase().contains("twin")?"Twin":"King");units.save(unit);}f.addFlashAttribute("success","Room type added.");return "redirect:/admin/hotels";}
 @PostMapping("/admin/rooms/{id}/edit") public String editRoom(@PathVariable Long id,@RequestParam String type,@RequestParam String description,@RequestParam double pricePerNight,@RequestParam int capacity,@RequestParam int quantity,RedirectAttributes f){Room r=rooms.findById(id).orElseThrow();long existing=units.countByRoomId(id);if(type.isBlank()||description.isBlank()||pricePerNight<1||capacity<1||quantity<existing){f.addFlashAttribute("error","Enter valid room details; inventory cannot be lower than registered individual rooms.");return "redirect:/admin/hotels";}r.setType(type.trim());r.setDescription(description.trim());r.setPricePerNight(pricePerNight);r.setCapacity(capacity);r.setQuantity(quantity);r=rooms.save(r);for(long i=existing+1;i<=quantity;i++){RoomUnit unit=new RoomUnit();unit.setRoom(r);unit.setRoomNumber(String.valueOf((r.getId()%9+1)*100+i));unit.setFloor((int)((i-1)/10)+1);unit.setBedType(r.getType().toLowerCase().contains("twin")?"Twin":"King");units.save(unit);}f.addFlashAttribute("success","Room type updated.");return "redirect:/admin/hotels";}
 @PostMapping("/admin/rooms/{id}/delete") public String deleteRoom(@PathVariable Long id,RedirectAttributes f){if(bookings.findAll().stream().anyMatch(b->b.getRoom().getId().equals(id)))f.addFlashAttribute("error","This room type has booking history and cannot be removed.");else{units.deleteAll(units.findByRoomId(id));rooms.deleteById(id);f.addFlashAttribute("success","Room type removed.");}return "redirect:/admin/hotels";}
 @GetMapping("/admin/bookings") public String adminBookings(@RequestParam(required=false)String q,@RequestParam(required=false)String guest,@RequestParam(required=false)String room,@RequestParam(required=false)LocalDate date,@RequestParam(required=false)String status,Model m){var list=bookings.findAll(Sort.by(Sort.Direction.DESC,"id"));if(q!=null&&!q.isBlank())list=list.stream().filter(b->b.getReference().toLowerCase().contains(q.toLowerCase())||b.getGuestName().toLowerCase().contains(q.toLowerCase())||b.getGuestEmail().toLowerCase().contains(q.toLowerCase())||b.getRoom().getHotel().getName().toLowerCase().contains(q.toLowerCase())).toList();if(guest!=null&&!guest.isBlank())list=list.stream().filter(b->b.getGuestName().toLowerCase().contains(guest.toLowerCase())||b.getGuestEmail().toLowerCase().contains(guest.toLowerCase())).toList();if(room!=null&&!room.isBlank())list=list.stream().filter(b->(b.getRoomUnit()!=null&&b.getRoomUnit().getRoomNumber().toLowerCase().contains(room.toLowerCase()))||b.getRoom().getType().toLowerCase().contains(room.toLowerCase())).toList();if(date!=null)list=list.stream().filter(b->!date.isBefore(b.getCheckIn())&&date.isBefore(b.getCheckOut())).toList();if(status!=null&&!status.isBlank())list=list.stream().filter(b->b.getStatus().equals(status)).toList();m.addAttribute("bookings",list);m.addAttribute("q",q);m.addAttribute("guest",guest);m.addAttribute("room",room);m.addAttribute("date",date);m.addAttribute("statusFilter",status);return "admin/bookings";}
 @GetMapping("/admin/bookings/{id}") public String adminBookingDetails(@PathVariable Long id,Model m){m.addAttribute("booking",bookings.findById(id).orElseThrow());return "admin/booking-detail";}
 @PostMapping("/admin/bookings/{id}/status") public String updateStatus(@PathVariable Long id,@RequestParam String status,RedirectAttributes f){try{bookingService.updateStatus(id,status);f.addFlashAttribute("success","Booking status updated.");}catch(IllegalArgumentException ex){f.addFlashAttribute("error",ex.getMessage());}return "redirect:/admin/bookings";}
 @GetMapping("/admin/users") public String adminUsers(Model m){m.addAttribute("users",accounts.findAll(Sort.by("name")));return "admin/users";}
 @PostMapping("/admin/users/{id}/toggle") public String toggleUser(@PathVariable Long id,Authentication auth,RedirectAttributes f){Account a=accounts.findById(id).orElseThrow();if(!a.getRole().equals("USER"))f.addFlashAttribute("error","Administrator accounts cannot be changed from user management.");else{a.setEnabled(!a.isEnabled());accounts.save(a);f.addFlashAttribute("success","Account access updated.");}return "redirect:/admin/users";}
}
